<script lang="ts">import { passwordPattern, passwordHelp } from '$lib/password'; let { data, form } = $props();</script>
<section class="card password"><p class="eyebrow">Account security</p><h1>{data.needsPassword ? 'Choose your personal password.' : 'Change your password.'}</h1><p class="muted">{data.needsPassword ? 'Your profile and room history are ready. Set a password once to replace the old PIN login.' : 'Changing your password signs out other saved sessions.'}</p><form method="POST">{#if !data.needsPassword}<label for="current">Current password</label><input id="current" name="current" type="password" required autocomplete="current-password" />{/if}<label for="password">New password</label><input id="password" name="password" type="password" autocomplete="new-password" required minlength="10" maxlength="72" pattern={passwordPattern} aria-describedby="password-help" /><p id="password-help" class="muted">{passwordHelp}</p><label for="confirm">Confirm password</label><input id="confirm" name="confirm" type="password" autocomplete="new-password" required minlength="10" maxlength="72" />{#if form?.message}<p class="error" role="alert">{form.message}</p>{/if}<button class="button">Save password and continue</button></form></section>
<style>.password{max-width:520px;margin:4vh auto}.button{margin-top:24px}</style>
